// Step: Check Available Drones
const payload = $input.first().json.body || $input.first().json;
const drones = payload.resources?.drones || [
  {
    id: 'drone-101',
    callsign: 'UAV Echo-1',
    model: 'Matrice 300 RTK',
    flightStatus: 'STANDBY_PAD',
    batteryPercentage: 94,
    role: 'THERMAL_RECON'
  },
  {
    id: 'drone-102',
    callsign: 'UAV Talon-2',
    model: 'Mavic 3 Thermal',
    flightStatus: 'STANDBY_PAD',
    batteryPercentage: 88,
    role: 'SEARCH_AND_RESCUE'
  },
  {
    id: 'drone-103',
    callsign: 'UAV Lifeline-3',
    model: 'Heavy-Lift Octocopter',
    flightStatus: 'STANDBY_PAD',
    batteryPercentage: 76,
    role: 'SUPPLY_AIRDROP'
  }
];

const availableDrones = drones.filter(d => 
  d.batteryPercentage > 30 && 
  (d.flightStatus === 'STANDBY_PAD' || d.flightStatus === 'READY' || d.flightStatus === 'STANDBY')
);

return [{
  json: {
    ...payload,
    totalFleetCount: drones.length,
    availableDrones,
    hasAvailableDrone: availableDrones.length > 0
  }
}];

// Step: Select Available Drone
const data = $input.first().json;

if (!data.hasAvailableDrone || data.availableDrones.length === 0) {
  throw new Error('No operational UAV units currently available on pad.');
}

// Select highest battery drone matching the mission
const selectedDrone = [...data.availableDrones].sort((a, b) => b.batteryPercentage - a.batteryPercentage)[0];

return [{
  json: {
    ...data,
    selectedDrone
  }
}];

// Step: Create Mission
const data = $input.first().json;
const drone = data.selectedDrone;
const targetZone = data.incident?.primaryLocation?.name || 'Zone A';

const mission = {
  missionId: `MSN-${Date.now().toString(36).toUpperCase()}`,
  droneId: drone.id,
  droneCallsign: drone.callsign,
  model: drone.model,
  targetZone,
  flightPattern: 'PERIMETER_GRID_RECON',
  targetAltitudeMeters: 45,
  payload: 'Thermal FLIR + Floatation Vest Drop',
  flightStatus: 'MISSION_CREATED',
  createdAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    mission
  }
}];

// Step: Update Mission Status (Takeoff clearance)
const data = $input.first().json;

const updatedMission = {
  ...data.mission,
  flightStatus: 'AIRBORNE_PATROL',
  groundSpeedKmH: 38.5,
  telemetryLinkStrength: 98,
  clearedAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    mission: updatedMission,
    droneWorkflowStatus: 'IN_FLIGHT'
  }
}];
